<script setup>
import {ref,onMounted,onBeforeUnmount,computed} from 'vue'
import {request} from './client'
import {planView,paymentLabel,hostedCheckout} from './contracts'
import './release.css'
const props=defineProps({controlPlane:Boolean})
const data=ref(null),error=ref(''),busy=ref(false),tenant=ref(''),plan=ref('STARTER'),quote=ref(null),attempt=ref(null)
let timer,disposed=false
const current=computed(()=>props.controlPlane?data.value?.organizations?.find(o=>o.name===tenant.value):null)
const subscription=computed(()=>planView(props.controlPlane?current.value?.subscription:data.value?.subscription))
async function run(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){data.value=await request('release',props.controlPlane?'billing':'workspace',{},'GET');if(props.controlPlane&&!tenant.value)tenant.value=data.value.organizations[0]?.name||''}
async function refresh(){await run(load)}
async function getQuote(){quote.value=null;await run(async()=>{quote.value=await request('subscription_payments','quote',{tenant:tenant.value,plan:plan.value})})}
async function checkout(){await run(async()=>{const r=await request('subscription_payments','checkout',{quote:quote.value.quote});sessionStorage.setItem('sisu-subscription-attempt',r.attempt);location.assign(hostedCheckout(r.redirect_url))})}
async function poll(){if(disposed)return;try{const id=sessionStorage.getItem('sisu-subscription-attempt');if(!id)return;attempt.value=await request('subscription_payments','status',{attempt:id},'GET');if(['created','pending'].includes(attempt.value.status)){timer=setTimeout(poll,10000)}else await load()}catch(e){error.value=e.message}}
onMounted(async()=>{await refresh();if(props.controlPlane)poll()});onBeforeUnmount(()=>{disposed=true;clearTimeout(timer)})
</script>
<template><section class="release"><h1>Organization plan & usage</h1><a v-if="!controlPlane" href="/campus">Return to campus</a> · <a href="/api/method/logout">Sign out</a><p>Subscription access is determined by the server. A checkout return does not confirm payment.</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="busy" role="status">Loading subscription…</p><button class="button subtle" :disabled="busy" @click="refresh">Refresh status</button>
<template v-if="data"><label v-if="controlPlane">Organization<select v-model="tenant" @change="quote=null"><option v-for="o in data.organizations" :key="o.name" :value="o.name">{{o.title}} · {{o.site_hostname}}</option></select></label><p v-if="controlPlane&&!data.organizations.length">No organization billing account is assigned to this login. Contact the platform owner.</p>
<article class="panel"><h2>{{subscription.plan||'No subscription'}}</h2><p class="status">{{subscription.state}} · {{subscription.available===false?'Access unavailable':'Server policy applies'}}</p><p>Starts {{subscription.starts_at||'—'}} · Ends {{subscription.ends_at||'—'}} · Grace {{subscription.grace_until||'—'}}</p><p>Support: {{subscription.support_tier||'standard'}}</p><div class="grid"><div><h3>Configured features</h3><p v-if="subscription.plan==='CUSTOM'" class="muted">Effective CUSTOM configuration. Override history is managed on the control plane.</p><ul><li v-for="(enabled,name) in subscription.features" :key="name">{{name}}: {{enabled?'Included':'Not included'}}</li></ul></div><div><h3>Allocations</h3><p v-for="(limit,name) in subscription.limits" :key="name">{{name}}: {{limit}}</p></div></div><details v-if="Object.keys(subscription.overrides).length"><summary>Custom overrides</summary><pre>{{subscription.overrides}}</pre></details></article>
<article v-if="!controlPlane" class="panel"><h2>Organization usage</h2><p>Storage backend: {{data.storage_backend}}. No external storage is implied.</p><p>Storage: {{data.storage.used}} / {{data.storage.limit}} bytes · {{data.storage.remaining}} remaining</p><div v-if="data.usage"><p v-for="(v,k) in data.usage.usage" :key="k">{{k}}: {{v.used}} / {{v.limit}} · {{v.remaining}} remaining · {{v.period}}</p><p>{{data.usage.ai_reset}}</p></div><p v-else>Detailed organization usage is available to the Institute Admin.</p><a v-if="data.billing_url" class="button primary" :href="data.billing_url" target="_blank" rel="noopener">Open secure SISU billing portal</a><p v-else class="muted">Contact your Institute Admin or platform owner to renew. Billing uses a separate control-plane login.</p></article>
<template v-else-if="current"><article class="panel"><h2>Select or renew a plan</h2><label>Plan<select v-model="plan" @change="quote=null"><option v-for="p in data.plans" :key="p.name">{{p.name}}</option></select></label><p>CUSTOM pricing uses the assigned contract. The confirmed server quote is authoritative.</p><button class="button primary" :disabled="busy" @click="getQuote">Get server quote</button><div v-if="quote"><p>{{quote.plan}} · {{quote.currency}} {{(quote.total_minor/100).toFixed(2)}} · Expires {{quote.expires_at}}</p><button class="button primary" :disabled="busy" @click="checkout">Confirm and open hosted checkout</button></div><p v-if="attempt" role="status">{{paymentLabel(attempt.status)}} · {{attempt.name}}</p><p>After settlement, the operator must deliver the updated signed policy to your tenant site. Tenant usage is not queried across databases.</p></article><article class="panel"><h2>Recent payment attempts</h2><p v-if="!current.payments.length">No payment attempts.</p><p v-for="p in current.payments" :key="p.name">{{paymentLabel(p.status)}} · {{p.currency}} {{(p.amount_minor/100).toFixed(2)}} · {{p.creation}}</p></article></template></template></section></template>
